def audit(job,out):
 need(not out.exists(),'Fresh failure evidence output');out.mkdir(parents=True);current=json.loads((job/'run.json').read_text());cap=current['capture'];need(cap['status']=='captured'and cap['returncode']==0 and cap['archive_sha256']==ARCHIVE and digest(cap['archive'])==ARCHIVE,'Exact root-owned quiescent failed archive')
 data,ids=read_archive(cap['archive'],cap['captured_run_manifest_sha256']);m=json.loads(data['job/run.json']);member,uart_identity=select_guest_uart(data,ids);raw=data[member];text=raw.decode('utf-8','strict');lines=text.splitlines();rows=[json.loads(x.split(' ',1)[1])for x in lines if x.startswith('IRIS_REGION ')];want=[(c,h,c['expected_checksums_by_hart'][h])for c in host_cases()[:2]for h in c['active_harts']]
 need(len(rows)==6,'Exact six observed scalar rows');previous={}
 for row,(case,h,expected)in zip(rows,want):
  need(all(type(row.get(k))is int for k in ['hart','hart_mask','checksum','start_cycle','end_cycle','instret_delta']),'Typed actual prefix')
  need(row['case_id']==case['id']and row['hart']==h and row['hart_mask']==7 and row['role']=='scalar.compute'and row['region']=='kernel'and row['checksum']==expected,'Independent complete scalar prefix')
  need(0<=row['start_cycle']<row['end_cycle']<2**64 and 0<row['instret_delta']<2**64 and row['start_cycle']>=previous.get(h,0),'Actual prefix counters');previous[h]=row['end_cycle']
 need([json.loads(x.split(' ',1)[1])for x in lines if x.startswith('IRIS_UART_PROFILE ')]==[PROFILE],'Actual DIV135')
 need(not any(x.startswith('IRIS_BATCH_DONE ')for x in lines)and not any(r['case_id']=='zephyr.vme.yield'for r in rows),'No vector-phase result or invented DONE')
 script_member=member.rsplit('/',1)[0]+'/sim-run.sh';elf_member='job/manager/workloads/iris-batch/batch.elf'
 with tarfile.open(cap['archive'],'r:gz')as t:
  script=t.extractfile(script_member).read();copy=t.extractfile('job/optional-observability/sim-run.sh').read();elf=t.extractfile(elf_member).read();post=t.extractfile('job/postrun-memory-observation-v2/observation.json').read()if'job/postrun-memory-observation-v2/observation.json'in ids else None
 need(hashlib.sha256(script).hexdigest()==ids[script_member]and script==copy,'Exact matching wrapper copies')
 w=WRAPPER.fullmatch(script.decode());head=START.fullmatch(lines[0]);tail=re.fullmatch(r'Script done on (?P<stamp>'+STAMP+r') \[COMMAND_EXIT_CODE="124"\]',lines[-1]);need(w is not None and head is not None and head['command']==w['command']and tail is not None,'Actual unique source-bound host watchdog124 envelope')
 need(text.count('COMMAND_EXIT_CODE')==1 and text.count('Script started')==1 and text.count('Script done')==1,'Unique failure envelope')
 start=datetime.datetime.fromisoformat(head['stamp']);end=datetime.datetime.fromisoformat(tail['stamp']);need(start<=end and(end-start).total_seconds()<=360,'Ordered bounded host timestamps')
 need([(c['task'],c['status'],c['returncode'],c['timed_out'])for c in m['commands']]==[(t,'passed',0,False)for t in ['kill','infrasetup','runworkload','kill']]and current['cleanup_status']==m['cleanup_status']=='passed'and current.get('cleanup_error')is None,'All managed tasks/owned cleanup passed despite guest failure')
 need(hashlib.sha256(elf).hexdigest()==m['elf_sha256']==ELF,'Exact failed mixed9 ELF')
 (out/'observed.elf').write_bytes(elf);(out/'uartlog').write_bytes(raw);(out/'sim-run.sh').write_bytes(script)
 sys.path.insert(0,str(ROOT/'timing'));from fp8_format_functional_audit_v1 import Elf
 e=Elf(out/'observed.elf');checks={0x800005bc:(4,0xf1402773),0x8000061e:(4,0x1567e963),0x8000303c:(4,0xf14027f3),0x80003042:(4,0x04f4e663),0x8000305e:(4,0x6bb040ef),0x8000306e:(4,0x0c007057),0x80004016:(4,0xf14026f3),0x8000401c:(4,0x02079713),0x80004020:(4,0x0016b513),0x80004024:(2,0xe83a),0x80004040:(2,0xcc42),0x80004048:(2,0xfc14),0x8000404a:(2,0xe84c),0x80004066:(2,0xf47c)}
 for pc,(size,value)in checks.items():need(int.from_bytes(e.read(pc,size),'little')==value,'Actual physical-ID/initialization guard instruction '+hex(pc))
 b=ROOT/'build/zephyr-firesim-uart/5e6/mixed-build';z=ROOT/'third_party/zephyr-iris';config=(b/'zephyr/.config').read_text();dt=(b/'zephyr/include/generated/zephyr/devicetree_generated.h').read_text();need('CONFIG_RV_BOOT_HART=0\n'in config and 'fn(DT_N_S_cpus_S_cpu_0) fn(DT_N_S_cpus_S_cpu_1) fn(DT_N_S_cpus_S_cpu_2)'in dt,'Compiled boot0 plus deterministic DT CPU order')
 paths=[Path(__file__).resolve(),ROOT/'zephyr/fpga_mixed9_v1.py',ROOT/'zephyr/script_envelope_v3.py',ROOT/'firesim/analyze_campaign.py',ROOT/'firesim/batch_runner.py',ROOT/'build/zephyr-mixed9-FPGA-normal-validation-v1/report.json',ROOT/'firesim/HART2_VECTOR_INVESTIGATION.md',ROOT/'firesim/FLUSH_FRONTIER_OUTCOMES.md',ROOT/'build/phase-watch-source-liveness-audit-v1/report.json',ROOT/'build/phase-watch-control-pair-closure-v1/report.json',ROOT/'build/flush-frontier-one-shot-closure-v1/report.json',ROOT/'build/flush-frontier-one-shot-v2/no-drain-proof.json',ROOT/'build/rocket-vset-cursor-source-audit-v1/report.json',ROOT/'build/zephyr-hart2-vreg-shift64-v1/layout-slack-proof.json',ROOT/'build/zephyr-hart2-minimal-nops-v1/layout-proof.json',z/'arch/riscv/include/kernel_arch_func.h',z/'arch/riscv/core/reset.S',z/'arch/riscv/core/smp.c',z/'arch/riscv/core/fpu.c',z/'arch/riscv/core/iris_vme.c',z/'kernel/smp.c',ROOT/'benchmarks/zephyr/src/main.c',b/'zephyr/.config',b/'zephyr/zephyr.dts',b/'zephyr/include/generated/zephyr/devicetree_generated.h']
 strict=json.loads(paths[5].read_text());need(strict['pass']is False and strict['archive_verified']is True and strict['archive_sha256']==ARCHIVE,'Strict normal analyzer still refuses this workload')
 post_record=json.loads(post)if post else None
 if post:(out/'postrun-observation.json').write_bytes(post)
 report=dict(schema='iris.Zephyr_mixed9_verified_bounded_failure.v1',evidence_verified=True,workload_pass=False,normal_functional_qualification=False,status='guest_watchdog124_with_verified_complete_scalar_prefix',archive_sha256=ARCHIVE,archived_manifest_sha256=cap['captured_run_manifest_sha256'],guest_uart=uart_identity,ELF_sha256=ELF,actual_scalar_regions=6,scalar_prefix_independent_goldens=True,missing_vector_phase_regions=3,actual_DONE_present=False,guest_exit_status=124,manager_tasks_all_return0=True,cleanup_passed=True,optional_postdriver_observation=post_record,postdriver_scope='Optional source-bound observer refuses nonzero guest exit separately; no new configuration measurement is inferred.',physical_vs_logical=dict(printed_hart='Actual mhartid CSR captured perworker',runtime_first6_harts=[0,1,2],boot_hart=0,DT_CPU_order=[0,1,2],logical_to_physical_given_compiled_boot=[0,1,2],arrival_order_affects_mapping=False,compiled_guard_instructions=len(checks),app_VME_route='actual_mhartid<2',API_VME_guard='independent mhartid>1 refusal before tilezero'),source_facts=['All three operation2 startgates are released; main prints no perworker vector result until all three finished semaphores arrive. Missing all3 rows cannot identify whichhart is waiting.','Compute firstuse calls iris_vme_enable before measured mcycle; its irq_lock compiles to z_smp_global_lock before firstVSET and tilezero. Sourceglobal IRQlock can be held during lazy firstrestore; actual lock state is unobserved.','Hart2 skips VME API and enters ordinaryRVV path; its firstVSET can also cause lazy restore. No evidence proves any of these VSET/restore instructions actually executed at failure.','Compiled kernel has fourm8 restore groups; this is capability/source presence, not actual execution proof.','Actual source cursor uses +&r, and existing exact-layout/source-bypass/capacity audits already bound the simple operand-clobber/counterwrap/clock-gating hypotheses. Those are not rootcause proofs.'],actual_stall_PC_known=False,actual_stalled_hart_known=False,cause_proven=False,source_image_association_verified=False,calibration_usable=False,timing_labels_used=False,hardware_contacted=False,network_contacted=False,input_sha256={str(p):digest(p)for p in paths})
 report['artifact_sha256']={p.name:digest(p)for p in out.iterdir()if p.is_file()};(out/'report.json').write_text(json.dumps(report,indent=2)+'\n');return report
