 p=argparse.ArgumentParser(__doc__);p.add_argument('job',type=Path);p.add_argument('--output',type=Path,required=True);a=p.parse_args();r=audit(a.job.resolve(),a.output.resolve());print(json.dumps(dict(evidence_verified=r['evidence_verified'],workload_pass=r['workload_pass'],actual_scalar_regions=r['actual_scalar_regions'],guest_exit_status=r['guest_exit_status'],report_sha256=digest(a.output/'report.json'))))
